create or replace function public.pb162_popup_upsert(p_id uuid default null,p_url_gambar text default null,p_judul text default null,p_deskripsi text default null,p_file_url text default null,p_urutan integer default 0) returns public.konfigurasi_popup language plpgsql security definer set search_path=public as $$ declare v_row public.konfigurasi_popup; begin if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if; if coalesce(trim(p_url_gambar),'')='' then raise exception 'URL_GAMBAR_REQUIRED'; end if; if p_id is null then update public.konfigurasi_popup set is_active=false where is_active=true; insert into public.konfigurasi_popup(url_gambar,judul,deskripsi,is_active,urutan,file_url) values(trim(p_url_gambar),nullif(trim(p_judul),''),nullif(trim(p_deskripsi),''),true,coalesce(p_urutan,0),nullif(trim(p_file_url),'')) returning * into v_row; else if not exists(select 1 from public.konfigurasi_popup where id=p_id) then raise exception 'POPUP_NOT_FOUND'; end if; update public.konfigurasi_popup set is_active=false where id<>p_id and is_active=true; update public.konfigurasi_popup set url_gambar=trim(p_url_gambar),judul=nullif(trim(p_judul),''),deskripsi=nullif(trim(p_deskripsi),''),is_active=true,urutan=coalesce(p_urutan,urutan),file_url=nullif(trim(p_file_url),'') where id=p_id returning * into v_row; end if; return v_row; end; $$;
create or replace function public.pb162_popup_set_active(p_id uuid) returns public.konfigurasi_popup language plpgsql security definer set search_path=public as $$ declare v_row public.konfigurasi_popup; begin if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if; update public.konfigurasi_popup set is_active=false where is_active=true and id<>p_id; update public.konfigurasi_popup set is_active=true where id=p_id returning * into v_row; if v_row.id is null then raise exception 'POPUP_NOT_FOUND'; end if; return v_row; end; $$;
create or replace function public.pb162_popup_delete(p_id uuid) returns boolean language plpgsql security definer set search_path=public as $$ declare v_active boolean; v_next uuid; begin if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if; select is_active into v_active from public.konfigurasi_popup where id=p_id; if not found then raise exception 'POPUP_NOT_FOUND'; end if; delete from public.konfigurasi_popup where id=p_id; if coalesce(v_active,false) then select id into v_next from public.konfigurasi_popup order by urutan asc,created_at desc limit 1; if v_next is not null then update public.konfigurasi_popup set is_active=true where id=v_next; end if; end if; return true; end; $$;
grant execute on function public.pb162_popup_upsert(uuid,text,text,text,text,integer) to authenticated;
grant execute on function public.pb162_popup_set_active(uuid) to authenticated;
grant execute on function public.pb162_popup_delete(uuid) to authenticated;
